package tests

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"

	"exercise/src/prefs"
)

func do(t *testing.T, h http.Handler, method, path, body string) (int, prefs.Preferences, string) {
	t.Helper()
	req := httptest.NewRequest(method, path, strings.NewReader(body))
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, req)
	var p prefs.Preferences
	json.Unmarshal(rec.Body.Bytes(), &p)
	return rec.Code, p, rec.Body.String()
}

func newServer() (http.Handler, *prefs.MemoryStore) {
	store := prefs.NewMemoryStore()
	return prefs.NewHandler(store), store
}

func TestGetReturnsDefaultsForNewUser(t *testing.T) {
	h, _ := newServer()
	code, p, body := do(t, h, "GET", "/users/u1/preferences", "")
	t.Logf("GET body: %s", strings.TrimSpace(body))
	if code != 200 || !p.EmailAlerts || p.DigestHour != 8 {
		t.Fatalf("GET = %d %+v", code, p)
	}
}

func TestRenameKeepsEmailAlertsOn(t *testing.T) {
	h, _ := newServer()
	code, p, _ := do(t, h, "PATCH", "/users/u1/preferences", `{"displayName":"Dana"}`)
	if code != 200 || p.DisplayName != "Dana" {
		t.Fatalf("PATCH = %d %+v", code, p)
	}
	if !p.EmailAlerts {
		t.Fatal("renaming a user turned emailAlerts off, but the request never mentioned it")
	}
}

func TestEmptyPatchChangesNothing(t *testing.T) {
	h, store := newServer()
	store.Put("u1", prefs.Preferences{DisplayName: "Dana", EmailAlerts: true, DigestHour: 17})
	code, p, _ := do(t, h, "PATCH", "/users/u1/preferences", `{}`)
	want := prefs.Preferences{DisplayName: "Dana", EmailAlerts: true, DigestHour: 17}
	if code != 200 || p != want {
		t.Fatalf("empty PATCH produced %d %+v, want unchanged %+v", code, p, want)
	}
}

func TestExplicitFalseTurnsAlertsOff(t *testing.T) {
	h, store := newServer()
	code, p, _ := do(t, h, "PATCH", "/users/u1/preferences", `{"emailAlerts":false}`)
	if code != 200 || p.EmailAlerts {
		t.Fatalf("PATCH emailAlerts=false = %d %+v", code, p)
	}
	if store.Get("u1").EmailAlerts {
		t.Fatal("the stored preferences still have alerts on")
	}
}

func TestExplicitTrueTurnsAlertsBackOn(t *testing.T) {
	h, store := newServer()
	store.Put("u1", prefs.Preferences{EmailAlerts: false, DigestHour: 6})
	_, p, _ := do(t, h, "PATCH", "/users/u1/preferences", `{"emailAlerts":true}`)
	if !p.EmailAlerts || p.DigestHour != 6 {
		t.Fatalf("got %+v, want alerts on and digestHour still 6", p)
	}
}

func TestDigestHourZeroIsHonoured(t *testing.T) {
	h, _ := newServer()
	code, p, _ := do(t, h, "PATCH", "/users/u1/preferences", `{"digestHour":0}`)
	if code != 200 || p.DigestHour != 0 {
		t.Fatalf("digestHour 0 gave %d %+v, want midnight", code, p)
	}
}

func TestUnknownFieldIsRejected(t *testing.T) {
	h, store := newServer()
	code, _, _ := do(t, h, "PATCH", "/users/u1/preferences", `{"emailAlert":false}`)
	if code != http.StatusBadRequest {
		t.Fatalf("status = %d for a misspelled field, want 400", code)
	}
	if !store.Get("u1").EmailAlerts {
		t.Fatal("a rejected request must not change anything")
	}
}

func TestOutOfRangeHourIsRejected(t *testing.T) {
	h, _ := newServer()
	code, _, _ := do(t, h, "PATCH", "/users/u1/preferences", `{"digestHour":30}`)
	if code != http.StatusUnprocessableEntity {
		t.Fatalf("status = %d for digestHour 30, want 422", code)
	}
}
